# main.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "eu-west-1"
  access_key = var.aws_access_key
  secret_key = var.aws_secret_key
}

resource "aws_instance" "web" {
  ami           = "ami-0e2e8d4a3c1d4e5f6"
  instance_type = "t3.micro"

  tags = {
    Name        = "web-server"
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_security_group" "web_sg" {
  name = "web-sg"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# variables.tf
variable "aws_access_key" {
  type      = string
  sensitive = true
}

variable "aws_secret_key" {
  type      = string
  sensitive = true
}

variable "environment" {
  type    = string
  default = "production"
}

# outputs.tf
output "instance_ip" {
  value       = aws_instance.web.public_ip
  description = "IP pública del servidor web"
}

output "instance_id" {
  value = aws_instance.web.id
}

# Añadir backend en main.tf
terraform {
  backend "s3" {
    bucket         = "mi-terraform-state"
    key            = "prod/terraform.tfstate"
    region         = "eu-west-1"
    encrypt        = true
    dynamodb_table = "terraform-locks"
  }
}

# Crear el bucket y tabla DynamoDB primero
# IAM: el usuario necesita permisos de S3 y DynamoDB

# modules/ec2-instance/main.tf
variable "instance_type" {}
variable "ami_id" {}
variable "name_prefix" {}

resource "aws_instance" "this" {
  ami           = var.ami_id
  instance_type = var.instance_type

  tags = {
    Name = "${var.name_prefix}-instance"
  }
}

# Usar el módulo
module "web_server" {
  source = "./modules/ec2-instance"

  instance_type = "t3.micro"
  ami_id        = "ami-0e2e8d4a3c1d4e5f6"
  name_prefix   = "web"
}
